import{_ as o,l as i,o as e,c as l,v as t,p as c,x as r,d as n,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"MSHR 与缺失下继续","description":"","frontmatter":{"title":"MSHR 与缺失下继续","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mshr.md","filePath":"cs/mshr.md","lastUpdated":1789023840000}'),p={name:"cs/mshr.md"};function E(m,a,A,S,_,C){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="mshr-与缺失下继续" tabindex="-1">MSHR 与缺失下继续 <a class="header-anchor" href="#mshr-与缺失下继续" aria-label="Permalink to &quot;MSHR 与缺失下继续&quot;">​</a></h1><div class="epigraph"><p>一次缺失不必堵住整条流水线：记下「谁在等这块」，后续命中与不相关缺失仍可走。</p><footer>—— 据 Kroft, Lockup-Free Instruction Fetch/Prefetch Cache Organization, ISCA 1981；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/cache-miss-types">上一课</a>把缺失分成强制、容量、冲突，并假定缺失期间核在等。五级 MEM 一拍完成是教学假设；DRAM 要许多拍。<a href="/cs/ipc-util">IPC 与利用率</a>已经对空转过敏。本课不重讲三分法。缺口是：阻塞 cache 让一次缺失冻结所有访存；非阻塞 cache 用缺失状态处理寄存器（MSHR）把「已发出的块请求」与流水线解开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>load 缺失若锁住 cache 端口，后面的命中 load、甚至不相关的缺失都不能发。乱序核窗口里常有多条独立 load。缺口不是更大的 cache，而是<strong>为每个未完成的块分配一项：地址、已回到的扇区、等待该块的 load/store 名单</strong>；填充完成再唤醒它们。</p><p>同一块上的第二次缺失不应再发一条 DRAM 事务：合并进已有 MSHR 项（secondary miss）。项用尽则仍要停，变成结构冒险。</p><p><span class="marginnote">Kroft 1981 的 lockup-free cache 是非阻塞设计的经典出处。MSHR 是后来教材用的名字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>缺失：查 MSHR 是否已有该块。无则分配项，向下一层发请求，流水线可继续执行不依赖该 load 的指令（五级顺序核则仍可能在提交点等；乱序核用 ROB 托住）。有则把本请求挂到该项。填充：数据写入 SRAM，按名单转发，释放项。</p>',9)),(e(),c(h,null,{default:r(()=>[d(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22cache%20%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20HITQ%5B%22MSHR%20%E5%B7%B2%E6%9C%89%E8%AF%A5%E5%9D%97%EF%BC%9F%22%5D%0A%20%20HITQ%20--%3E%7C%22%E6%9C%89%22%7C%20SEC%5B%22%E6%8C%82%E5%88%B0%E5%90%8C%E4%B8%80%E9%A1%B9%22%5D%0A%20%20HITQ%20--%3E%7C%22%E6%97%A0%22%7C%20ALLOC%5B%22%E5%88%86%E9%85%8D%20MSHR%EF%BC%8C%E5%8F%91%E4%B8%8B%E4%B8%80%E5%B1%82%22%5D%0A%20%20ALLOC%20--%3E%20FILL%5B%22%E5%A1%AB%E5%85%85%E5%90%8E%E5%94%A4%E9%86%92%E7%AD%89%E5%BE%85%E8%80%85%22%5D%0A%20%20SEC%20--%3E%20FILL%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>预取也可以占 MSHR：提前发的块与需求缺失抢项。那是下一课的交易，本课只承认项是共享资源。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>非阻塞把「缺失率」和「缺失延迟对 IPC 的杀伤」拆开：同样缺失次数，能继续做的有用功不同。阿姆达尔：未掩盖的那一段缺失延迟仍封顶加速。MSHR 深度、到 DRAM 的未完成事务数、写缓冲，都是队列容量。</p><p>顺序五级若不允许缺失下继续，本课几乎退化成「MEM 级暂停」。对象仍要先建立，后课乱序才吃满它。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入预取算法，不引入一致性下 MSHR 与探听的竞态（迟到的作废 vs 填充）。也不把 MSHR 当成 ISA。victim buffer 不是 MSHR：前者存刚踢的数据，后者存未完成的请求。</p><p>后课默认：cache 可以非阻塞；一次缺失不再默认冻结所有访存。主动把块请来是下一课预取。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MSHR 记下未完成块与等待者，允许缺失下继续。</li><li>同块二次缺失合并；项满则仍停。</li><li>预取与 MSHR 抢项，是下一课。</li><li>出处：Kroft, <em>ISCA</em>, 1981；Hennessy and Patterson, <em>CA:AQA</em> 非阻塞 cache。</li></ul>',9))])}const u=o(p,[["render",E]]);export{M as __pageData,u as default};
